// /internal/competitors — competitor intelligence. PIN-GATED SERVER-SIDE.
//
// Rule 9 exists because a CSS-only PIN curtain on reddenda.com/competitors
// served 303,451 bytes to any anonymous curl while showing an "enter the PIN"
// overlay. If the bytes reach the browser, the page is public. So the page
// HTML lives INSIDE this handler as a string and is serialized ONLY after the
// PIN check passes. An unauthenticated GET receives the entry form and not one
// byte of the intelligence.
//
// Auth: POST pin=<value> compared constant-time against ANSWERED_COMPETITORS_PIN.
// Success sets an HttpOnly HMAC cookie signed with ANSWERED_BRAIN_SECRET.
// Either env missing = 503 and no page, ever. Wrong PIN answers slowly.
//
// Not in the sitemap. noindex on public bytes is a request, not a control, so
// the control is that there are no public bytes.
'use strict';

const crypto = require('crypto');

const PIN = (process.env.ANSWERED_COMPETITORS_PIN || '').trim();
const SECRET = (process.env.ANSWERED_BRAIN_SECRET || '').trim();
const COOKIE = 'acomp';

const BASE_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8',
  'Cache-Control': 'no-store, no-cache, must-revalidate, private',
  'X-Robots-Tag': 'noindex, nofollow, noarchive',
  'Referrer-Policy': 'no-referrer',
  'X-Content-Type-Options': 'nosniff',
};

function sign(s) {
  return crypto.createHmac('sha256', SECRET).update(s).digest('base64url');
}
function makeToken() {
  const body = String(Date.now());
  return body + '.' + sign(body);
}
function validToken(tok) {
  if (!tok || !SECRET) return false;
  const i = String(tok).lastIndexOf('.');
  if (i < 1) return false;
  const body = String(tok).slice(0, i);
  const got = String(tok).slice(i + 1);
  const want = sign(body);
  const a = Buffer.from(got), b = Buffer.from(want);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return false;
  const age = Date.now() - Number(body);
  return Number.isFinite(age) && age >= 0 && age < 12 * 60 * 60 * 1000;
}
function pinOk(given) {
  if (!PIN || !given) return false;
  const a = Buffer.from(String(given)), b = Buffer.from(PIN);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
function readCookie(h) {
  const raw = (h && (h.cookie || h.Cookie)) || '';
  for (const part of raw.split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === COOKIE) return v.join('=');
  }
  return '';
}
function gatePage(msg) {
  return '<!doctype html><html lang="en"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<meta name="robots" content="noindex,nofollow,noarchive">'
    + '<title>Internal</title><style>body{margin:0;background:#0B0C0E;color:#F2F4F5;'
    + 'font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Helvetica,Arial,sans-serif}'
    + '.gate{max-width:420px;margin:16vh auto;padding:0 20px}h1{font-size:22px;margin:0 0 6px}'
    + 'p{color:#9AA2A8;font-size:13.5px;margin:6px 0}'
    + 'input{width:100%;background:#14171A;border:1px solid #2A2E33;border-radius:8px;'
    + 'padding:12px 14px;color:#fff;font:inherit;margin-top:12px}'
    + 'button{margin-top:10px;width:100%;background:#E3FF4F;color:#0B0C0E;border:0;border-radius:8px;'
    + 'padding:12px;font:inherit;font-weight:700;cursor:pointer}</style></head><body><div class="gate">'
    + '<h1>Internal page</h1><p>' + msg + '</p>'
    + '<form method="POST"><input name="pin" type="password" inputmode="numeric" autocomplete="off" autofocus>'
    + '<button type="submit">Enter</button></form></div></body></html>';
}

