exports.handler = async (event) => {
  const headers = event.headers || {};

  // Fail closed. No PIN configured means no page, not an open page.
  if (!PIN || !SECRET) {
    console.error('competitors: ANSWERED_COMPETITORS_PIN or ANSWERED_BRAIN_SECRET not set; refusing.');
    return { statusCode: 503, headers: BASE_HEADERS, body: gatePage('The gate is not configured. Nothing is served without it.') };
  }

  if (event.httpMethod === 'POST') {
    const raw = event.isBase64Encoded
      ? Buffer.from(event.body || '', 'base64').toString('utf8')
      : (event.body || '');
    const params = new URLSearchParams(raw);
    if (pinOk(params.get('pin'))) {
      return {
        statusCode: 200,
        headers: {
          ...BASE_HEADERS,
          'Set-Cookie': COOKIE + '=' + makeToken()
            + '; HttpOnly; Secure; SameSite=Strict; Path=/internal; Max-Age=43200',
        },
        body: PAGE_HTML,
      };
    }
    // A wrong PIN costs time and says nothing useful.
    await new Promise((r) => setTimeout(r, 600));
    return { statusCode: 401, headers: BASE_HEADERS, body: gatePage('That PIN is not right.') };
  }

  if (validToken(readCookie(headers))) {
    return { statusCode: 200, headers: BASE_HEADERS, body: PAGE_HTML };
  }
  return { statusCode: 200, headers: BASE_HEADERS, body: gatePage('This page is for the team. Enter the PIN.') };
};
